from fastapi import APIRouter, Depends, HTTPException, Requestfrom sqlalchemy.orm import Sessionfrom .. import schemas, database, crud, configfrom ..connectors import mock_connectorfrom ..auth import get_current_userrouter = APIRouter(prefix="/search", tags=["search"])settings = config.settings@router.post("/", response_model=schemas.SearchResponse)def do_search(request: schemas.SearchRequest, db: Session = Depends(database.get_db), current_user = Depends(get_current_user)):    qtype = request.type.lower()    qvalue = request.value.strip()    if qtype not in settings.CREDIT_COSTS:        raise HTTPException(status_code=400, detail="Tipo de consulta inválido")    cost = settings.CREDIT_COSTS[qtype]    if not crud.consume_credits(db, current_user.id, cost):        raise HTTPException(status_code=402, detail="Créditos insuficientes")    result = mock_connector.search_mock(qtype, qvalue)    summary = f"Resultado {qtype} para {qvalue}"    crud.log_search(db, current_user.id, qtype, qvalue, cost, summary, result, ip=None)    return schemas.SearchResponse(summary=summary, data=result, credits_used=cost)